window.PAGES = window.PAGES || {};
window.PAGES["postgresql"] = {"label":"🐘 PostgreSQL","body":"<h1 id=\"postgresql-100-interview-questions-answers\">🐘 PostgreSQL — 100 Interview Questions &amp; Answers</h1>\n<h3 id=\"ikki-tilli-qollanma-bilingual-reference\">Ikki tilli qo'llanma / Bilingual Reference</h3>\n<blockquote>\n<p><strong>Daraja / Level:</strong> Boshlang'ich → O'rta → Ilg'or → Ekspert<br />\n<strong>Tillar / Languages:</strong> O'zbek 🇺🇿 | English 🇬🇧<br />\n<strong>Maqsad / Goal:</strong> PostgreSQL intervyusiga to'liq tayyorgarlik</p>\n</blockquote>\n<hr />\n<h2 id=\"mundarija-table-of-contents\">📚 Mundarija / Table of Contents</h2>\n<ol>\n<li><a href=\"#1-asosiy-tushunchalar--basics\">Asosiy tushunchalar / Basics (1–25)</a></li>\n<li><a href=\"#2-orta-daraja--intermediate\">O'rta daraja / Intermediate (26–55)</a></li>\n<li><a href=\"#3-ilgor-daraja--advanced\">Ilg'or daraja / Advanced (56–80)</a></li>\n<li><a href=\"#4-ekspert-daraja--expert\">Ekspert daraja / Expert (81–100)</a></li>\n</ol>\n<hr />\n<h2 id=\"1-asosiy-tushunchalar-basics\">1. Asosiy tushunchalar / Basics</h2>\n<p><strong>1. PostgreSQL nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL — kuchli, ochiq manbali ob'ektga-relyatsion ma'lumotlar bazasi tizimi. 30+ yillik faol rivojlanishga ega va ishonchlilik, xususiyatlar to'plami va unumdorlik jihatidan yuqori obro'ga ega.<br />\n<strong>EN:</strong> PostgreSQL is a powerful, open-source object-relational database system with over 30 years of active development. It is known for reliability, feature richness, and performance.</p>\n</blockquote>\n<hr />\n<p><strong>2. PostgreSQL va MySQL o'rtasidagi asosiy farqlar?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL to'liq ACID muvofiq, murakkab so'rovlar, JSON, CTE, window funksiyalar, full-text search va kengaytmalarni yaxshiroq qo'llab-quvvatlaydi. MySQL sodda CRUD ilovalar uchun tezroq, lekin ilg'or funksiyalarda orqada qoladi.<br />\n<strong>EN:</strong> PostgreSQL is fully ACID-compliant, better supports complex queries, JSON, CTEs, window functions, full-text search, and extensions. MySQL is faster for simple CRUD apps but lags in advanced features.</p>\n</blockquote>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>PostgreSQL</th>\n<th>MySQL</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Litsenziya</td>\n<td>PostgreSQL (MIT-like)</td>\n<td>GPL / Commercial</td>\n</tr>\n<tr>\n<td>JSON</td>\n<td>To'liq qo'llab-quvvatlash</td>\n<td>Cheklangan</td>\n</tr>\n<tr>\n<td>Window funksiyalar</td>\n<td>✅</td>\n<td>Cheklangan</td>\n</tr>\n<tr>\n<td>Full ACID</td>\n<td>✅</td>\n<td>Faqat InnoDB</td>\n</tr>\n<tr>\n<td>Kengaytmalar</td>\n<td>Ko'p (PostGIS, pg_trgm)</td>\n<td>Kam</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<p><strong>3. ACID nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> ACID — ma'lumotlar bazasi tranzaksiyalarining 4 xususiyati:\n- <strong>A</strong>tomicity — tranzaksiya ya to'liq bajariladi, yo umuman bajarilmaydi\n- <strong>C</strong>onsistency — tranzaksiya MBni bir to'g'ri holatdan ikkinchisiga o'tkazadi\n- <strong>I</strong>solation — bir vaqtda bajarilayotgan tranzaksiyalar bir-birini ko'rmaydi\n- <strong>D</strong>urability — tranzaksiya tasdiqlangandan keyin, tizim ishlamay qolsa ham, ma'lumotlar saqlanadi<br />\n<strong>EN:</strong> ACID — 4 properties ensuring reliable database transactions: <strong>Atomicity</strong> (all or nothing), <strong>Consistency</strong> (valid state transition), <strong>Isolation</strong> (concurrent transactions don't interfere), <strong>Durability</strong> (committed data persists despite failures).</p>\n</blockquote>\n<hr />\n<p><strong>4. PostgreSQL da ma'lumot turlari (Data Types)?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Asosiy turlar: <code>INTEGER</code>, <code>BIGINT</code>, <code>NUMERIC</code>, <code>FLOAT</code>, <code>VARCHAR(n)</code>, <code>TEXT</code>, <code>BOOLEAN</code>, <code>DATE</code>, <code>TIMESTAMP</code>, <code>TIMESTAMPTZ</code>, <code>UUID</code>, <code>JSON</code>, <code>JSONB</code>, <code>ARRAY</code>, <code>BYTEA</code>, <code>SERIAL</code>.<br />\n<strong>EN:</strong> Key types: <code>INTEGER</code>, <code>BIGINT</code>, <code>NUMERIC</code>, <code>FLOAT</code>, <code>VARCHAR(n)</code>, <code>TEXT</code>, <code>BOOLEAN</code>, <code>DATE</code>, <code>TIMESTAMP</code>, <code>TIMESTAMPTZ</code>, <code>UUID</code>, <code>JSON</code>, <code>JSONB</code>, <code>ARRAY</code>, <code>BYTEA</code>, <code>SERIAL</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLE example (\n    id          SERIAL PRIMARY KEY,\n    name        VARCHAR(100) NOT NULL,\n    salary      NUMERIC(12, 2),\n    is_active   BOOLEAN DEFAULT TRUE,\n    created_at  TIMESTAMPTZ DEFAULT NOW(),\n    metadata    JSONB,\n    tags        TEXT[]\n);\n</code></pre>\n<hr />\n<p><strong>5. PRIMARY KEY va UNIQUE farqi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>PRIMARY KEY</code> — jadvalda faqat bitta bo'lishi mumkin, NULL qabul qilmaydi, avtomatik indeks yaratadi. <code>UNIQUE</code> — bir jadvalda bir nechta bo'lishi mumkin, NULL qabul qiladi (har bir NULL yagona hisoblanadi).<br />\n<strong>EN:</strong> <code>PRIMARY KEY</code> — only one per table, no NULLs, auto-creates index. <code>UNIQUE</code> — multiple per table, allows NULLs (each NULL is considered unique).</p>\n</blockquote>\n<hr />\n<p><strong>6. NULL nima va qanday ishlaydi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> NULL — qiymat yo'qligini bildiradi, nol yoki bo'sh satr emas. NULL bilan har qanday taqqoslash (<code>=</code>, <code>&lt;</code>, <code>&gt;</code>) <code>NULL</code> qaytaradi. Tekshirish uchun <code>IS NULL</code> yoki <code>IS NOT NULL</code> ishlatiladi.<br />\n<strong>EN:</strong> NULL means the absence of a value — not zero or empty string. Any comparison with NULL (<code>=</code>, <code>&lt;</code>, <code>&gt;</code>) returns NULL. Use <code>IS NULL</code> or <code>IS NOT NULL</code> to check.</p>\n</blockquote>\n<pre><code class=\"language-sql\">SELECT * FROM users WHERE phone IS NULL;\nSELECT COALESCE(phone, 'N/A') FROM users;  -- NULL o'rniga default qiymat\n</code></pre>\n<hr />\n<p><strong>7. Schema nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Schema — PostgreSQL da ma'lumotlar bazasi ichidagi mantiqiy nom maydoni. Jadvallar, ko'rinishlar, funksiyalar va boshqa ob'ektlarni guruhlaydi. Default schema <code>public</code>.<br />\n<strong>EN:</strong> A schema is a logical namespace within a PostgreSQL database that groups tables, views, functions, and other objects. Default schema is <code>public</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE SCHEMA hr;\nCREATE TABLE hr.employees (...);\nSET search_path TO hr, public;\n</code></pre>\n<hr />\n<p><strong>8. Sequence nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Sequence — ketma-ket yagona raqamlar yaratuvchi ob'ekt. <code>SERIAL</code> va <code>BIGSERIAL</code> ma'lumot turlari ichida avtomatik sequence yaratadi. <code>nextval()</code>, <code>currval()</code>, <code>setval()</code> funksiyalari bilan boshqariladi.<br />\n<strong>EN:</strong> A sequence generates unique sequential numbers. <code>SERIAL</code>/<code>BIGSERIAL</code> types create sequences automatically. Controlled via <code>nextval()</code>, <code>currval()</code>, <code>setval()</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE SEQUENCE order_seq START 1000 INCREMENT 1;\nSELECT nextval('order_seq');  -- 1000, 1001, ...\n\n-- Yoki SERIAL orqali\nCREATE TABLE orders (id SERIAL PRIMARY KEY);\n</code></pre>\n<hr />\n<p><strong>9. INDEX nima va nima uchun kerak?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Index — ma'lumotlarni tezroq qidirish uchun yaratilgan qo'shimcha ma'lumot tuzilmasi. WHERE, JOIN, ORDER BY da tezlikni oshiradi, lekin yozish operatsiyalari (<code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>) ni biroz sekinlashtiradi.<br />\n<strong>EN:</strong> An index is an auxiliary data structure for faster data retrieval. Speeds up WHERE, JOIN, ORDER BY but slightly slows write operations.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Oddiy index\nCREATE INDEX idx_users_email ON users(email);\n\n-- Ko'p ustunli index\nCREATE INDEX idx_orders_user_date ON orders(user_id, created_at DESC);\n\n-- Unikal index\nCREATE UNIQUE INDEX idx_users_email_unique ON users(email);\n</code></pre>\n<hr />\n<p><strong>10. Index turlari PostgreSQL da?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Asosiy index turlari:\n- <strong>B-tree</strong> (default) — tenglik va oraliq so'rovlar uchun\n- <strong>Hash</strong> — faqat tenglik (<code>=</code>) so'rovlari uchun\n- <strong>GiST</strong> — geometrik, to'liq matn qidirish uchun\n- <strong>GIN</strong> — massivlar, JSONB, to'liq matn uchun\n- <strong>BRIN</strong> — juda katta, fizik tartibda saqlangan jadvallar uchun<br />\n<strong>EN:</strong> Key index types: <strong>B-tree</strong> (default, range+equality), <strong>Hash</strong> (equality only), <strong>GiST</strong> (geometric, full-text), <strong>GIN</strong> (arrays, JSONB, full-text), <strong>BRIN</strong> (large physically-ordered tables).</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE INDEX idx_gin ON documents USING GIN(content_tsvector);\nCREATE INDEX idx_hash ON sessions USING HASH(session_token);\n</code></pre>\n<hr />\n<p><strong>11. VIEW nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> View — saqlangan SELECT so'rovi. Real ma'lumot saqlamaydi (oddiy view da), lekin jadval kabi so'ralishi mumkin. Murakkab so'rovlarni soddalashtiradi va xavfsizlik qatlamini ta'minlaydi.<br />\n<strong>EN:</strong> A view is a stored SELECT query. Regular views don't store data but can be queried like tables. They simplify complex queries and provide a security layer.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE VIEW active_users AS\nSELECT id, name, email\nFROM users\nWHERE is_active = TRUE;\n\nSELECT * FROM active_users;\n</code></pre>\n<hr />\n<p><strong>12. Materialized View nima va oddiy View dan farqi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Materialized View so'rov natijasini diskda saqlaydi — tez o'qish imkonini beradi, lekin ma'lumotlar eskirishi mumkin. <code>REFRESH MATERIALIZED VIEW</code> bilan yangilanadi.<br />\n<strong>EN:</strong> Materialized View physically stores the query result on disk — fast reads but data can become stale. Refreshed with <code>REFRESH MATERIALIZED VIEW</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE MATERIALIZED VIEW sales_summary AS\nSELECT date_trunc('month', created_at) as month,\n       SUM(total) as revenue\nFROM orders GROUP BY 1;\n\n-- Yangilash / Refresh\nREFRESH MATERIALIZED VIEW CONCURRENTLY sales_summary;\n</code></pre>\n<hr />\n<p><strong>13. JOIN turlari?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Asosiy JOIN turlari:\n- <strong>INNER JOIN</strong> — ikkala jadvalda mos yozuvlar\n- <strong>LEFT JOIN</strong> — chap jadvalning barcha yozuvlari + o'ngdan mos kelganlar\n- <strong>RIGHT JOIN</strong> — o'ng jadvalning barcha yozuvlari + chapdan mos kelganlar\n- <strong>FULL OUTER JOIN</strong> — ikkala jadvalning barcha yozuvlari\n- <strong>CROSS JOIN</strong> — kartezian ko'paytma<br />\n<strong>EN:</strong> <strong>INNER JOIN</strong> (matching rows in both), <strong>LEFT JOIN</strong> (all left + matching right), <strong>RIGHT JOIN</strong> (all right + matching left), <strong>FULL OUTER JOIN</strong> (all from both), <strong>CROSS JOIN</strong> (cartesian product).</p>\n</blockquote>\n<pre><code class=\"language-sql\">SELECT u.name, o.total\nFROM users u\nLEFT JOIN orders o ON u.id = o.user_id\nWHERE o.created_at &gt;= NOW() - INTERVAL '30 days';\n</code></pre>\n<hr />\n<p><strong>14. Subquery (Ichki so'rov) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Subquery — boshqa so'rov ichida joylashtirilgan so'rov. WHERE, FROM, SELECT, HAVING da ishlatilishi mumkin. Korrelyatsiyalangan (correlated) va korrelyatsiyalanmagan turlari bor.<br />\n<strong>EN:</strong> A subquery is a query nested inside another query. Can be used in WHERE, FROM, SELECT, HAVING. Can be correlated (references outer query) or non-correlated.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- WHERE da subquery\nSELECT name FROM users\nWHERE id IN (SELECT user_id FROM orders WHERE total &gt; 1000000);\n\n-- FROM da subquery (derived table)\nSELECT dept, AVG(salary) FROM (\n    SELECT department as dept, salary FROM employees WHERE is_active = TRUE\n) sub GROUP BY dept;\n</code></pre>\n<hr />\n<p><strong>15. CTE (Common Table Expression) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> CTE — <code>WITH</code> kalit so'zi bilan aniqlangan vaqtinchalik nomli natija to'plami. Murakkab so'rovlarni o'qilishi oson bo'laklarga ajratadi. Rekursiv CTE ham mumkin.<br />\n<strong>EN:</strong> CTE is a temporary named result set defined with <code>WITH</code>. Breaks complex queries into readable parts. Recursive CTEs are also supported.</p>\n</blockquote>\n<pre><code class=\"language-sql\">WITH monthly_sales AS (\n    SELECT date_trunc('month', created_at) AS month,\n           SUM(total) AS revenue\n    FROM orders\n    GROUP BY 1\n),\nranked AS (\n    SELECT *, RANK() OVER (ORDER BY revenue DESC) AS rank\n    FROM monthly_sales\n)\nSELECT * FROM ranked WHERE rank &lt;= 3;\n</code></pre>\n<hr />\n<p><strong>16. Window funksiyalar nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Window funksiyalar qatorlar guruhida hisob-kitob qiladi, lekin guruhlarni birlashtirmaydi (GROUP BY dan farqi). <code>OVER()</code> clause bilan ishlatiladi. <code>ROW_NUMBER()</code>, <code>RANK()</code>, <code>DENSE_RANK()</code>, <code>LAG()</code>, <code>LEAD()</code>, <code>SUM() OVER()</code> kabilar.<br />\n<strong>EN:</strong> Window functions perform calculations across a set of rows without collapsing them (unlike GROUP BY). Used with <code>OVER()</code> clause.</p>\n</blockquote>\n<pre><code class=\"language-sql\">SELECT\n    name,\n    department,\n    salary,\n    RANK() OVER (PARTITION BY department ORDER BY salary DESC) AS dept_rank,\n    LAG(salary) OVER (ORDER BY salary) AS prev_salary,\n    SUM(salary) OVER (PARTITION BY department) AS dept_total\nFROM employees;\n</code></pre>\n<hr />\n<p><strong>17. HAVING va WHERE farqi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>WHERE</code> — GROUP BY dan oldin individual qatorlarni filtrlaydi. <code>HAVING</code> — GROUP BY dan keyin guruhlarni filtrlaydi. Agregat funksiyalar (<code>COUNT</code>, <code>SUM</code>) faqat <code>HAVING</code> da ishlatilishi mumkin.<br />\n<strong>EN:</strong> <code>WHERE</code> filters individual rows before GROUP BY. <code>HAVING</code> filters groups after GROUP BY. Aggregate functions can only be used in <code>HAVING</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">SELECT department, COUNT(*) AS count, AVG(salary) AS avg_sal\nFROM employees\nWHERE is_active = TRUE          -- avval filtrlash / filter first\nGROUP BY department\nHAVING COUNT(*) &gt; 5             -- guruhni filtrlash / filter group\nORDER BY avg_sal DESC;\n</code></pre>\n<hr />\n<p><strong>18. DISTINCT qanday ishlaydi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>DISTINCT</code> — natija to'plamidagi takrorlanuvchi qatorlarni olib tashlaydi. <code>DISTINCT ON (ustun)</code> — ma'lum ustun bo'yicha birinchi qatorni qaytaradi (PostgreSQL xususiyati).<br />\n<strong>EN:</strong> <code>DISTINCT</code> removes duplicate rows from the result. <code>DISTINCT ON (column)</code> returns the first row for each distinct value of the specified column (PostgreSQL-specific).</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Barcha yagona shaharlar\nSELECT DISTINCT city FROM users;\n\n-- Har bir foydalanuvchining oxirgi buyurtmasi\nSELECT DISTINCT ON (user_id)\n    user_id, order_id, created_at\nFROM orders\nORDER BY user_id, created_at DESC;\n</code></pre>\n<hr />\n<p><strong>19. LIMIT va OFFSET nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>LIMIT</code> — qaytariladigan qatorlar sonini cheklaydi. <code>OFFSET</code> — ma'lum miqdordagi qatorlarni o'tkazib yuboradi. Sahifalash (pagination) uchun ishlatiladi, lekin katta OFFSET larda sekin ishlaydi.<br />\n<strong>EN:</strong> <code>LIMIT</code> caps the number of returned rows. <code>OFFSET</code> skips a number of rows. Used for pagination, but large OFFSET values are slow.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- 2-sahifa, har sahifada 10 ta\nSELECT * FROM products\nORDER BY id\nLIMIT 10 OFFSET 10;\n</code></pre>\n<hr />\n<p><strong>20. EXPLAIN va EXPLAIN ANALYZE nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>EXPLAIN</code> — so'rov bajarish rejasini ko'rsatadi (haqiqatan bajarmasdan). <code>EXPLAIN ANALYZE</code> — rejani ko'rsatadi VA so'rovni bajarib, haqiqiy vaqtni o'lchaydi. So'rovlarni optimallashtirish uchun muhim vosita.<br />\n<strong>EN:</strong> <code>EXPLAIN</code> shows the query execution plan without running it. <code>EXPLAIN ANALYZE</code> shows the plan AND executes the query, measuring actual time. Essential for query optimization.</p>\n</blockquote>\n<pre><code class=\"language-sql\">EXPLAIN ANALYZE\nSELECT u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON u.id = o.user_id\nGROUP BY u.id, u.name;\n</code></pre>\n<hr />\n<p><strong>21. Transaction (Tranzaksiya) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Tranzaksiya — yagona mantiqiy birlik sifatida bajarilishi kerak bo'lgan SQL operatsiyalar ketma-ketligi. <code>BEGIN</code>/<code>START TRANSACTION</code> bilan boshlanadi, <code>COMMIT</code> yoki <code>ROLLBACK</code> bilan tugaydi.<br />\n<strong>EN:</strong> A transaction is a sequence of SQL operations executed as a single logical unit. Starts with <code>BEGIN</code>/<code>START TRANSACTION</code>, ends with <code>COMMIT</code> or <code>ROLLBACK</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">BEGIN;\n\nUPDATE accounts SET balance = balance - 500000 WHERE id = 1;\nUPDATE accounts SET balance = balance + 500000 WHERE id = 2;\n\n-- Agar xato bo'lsa / If error:\nROLLBACK;\n\n-- Agar hammasi yaxshi / If all good:\nCOMMIT;\n</code></pre>\n<hr />\n<p><strong>22. SAVEPOINT nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> SAVEPOINT — tranzaksiya ichidagi belgi nuqtasi. Tranzaksiyaning faqat bir qismini orqaga qaytarish (<code>ROLLBACK TO SAVEPOINT</code>) imkonini beradi, butun tranzaksiyani bekor qilmasdan.<br />\n<strong>EN:</strong> SAVEPOINT is a marker within a transaction allowing partial rollback (<code>ROLLBACK TO SAVEPOINT</code>) without canceling the entire transaction.</p>\n</blockquote>\n<pre><code class=\"language-sql\">BEGIN;\nINSERT INTO logs (...) VALUES (...);\nSAVEPOINT sp1;\n\nUPDATE orders SET status = 'shipped' WHERE id = 5;\n-- Agar bu xato bo'lsa / If this fails:\nROLLBACK TO SAVEPOINT sp1;\n\nCOMMIT;\n</code></pre>\n<hr />\n<p><strong>23. FOREIGN KEY va CASCADE?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Foreign Key ikki jadval o'rtasidagi bog'liqlikni ta'minlaydi. <code>ON DELETE CASCADE</code> — asosiy yozuv o'chirilganda bog'liq yozuvlar ham o'chadi. <code>ON DELETE SET NULL</code> — NULL ga o'rnatadi. <code>ON DELETE RESTRICT</code> — o'chirishni bloklaydi.<br />\n<strong>EN:</strong> Foreign Key enforces referential integrity. <code>ON DELETE CASCADE</code> deletes related rows. <code>ON DELETE SET NULL</code> sets FK to NULL. <code>ON DELETE RESTRICT</code> blocks deletion.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLE orders (\n    id      SERIAL PRIMARY KEY,\n    user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n    ...\n);\n</code></pre>\n<hr />\n<p><strong>24. CHECK constraint nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> CHECK — ustun qiymatiga shart qo'yadi. Shart yolg'on bo'lsa, yozuv rad etiladi.<br />\n<strong>EN:</strong> CHECK enforces a condition on column values. If the condition is false, the row is rejected.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLE employees (\n    id      SERIAL PRIMARY KEY,\n    salary  NUMERIC CHECK (salary &gt; 0),\n    age     INT CHECK (age BETWEEN 18 AND 65),\n    email   TEXT CHECK (email LIKE '%@%')\n);\n</code></pre>\n<hr />\n<p><strong>25. DEFAULT qiymatlar?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>DEFAULT</code> — yangi yozuv qo'shilganda qiymat ko'rsatilmasa, avtomatik beriladigan qiymat. Statik qiymat, funksiya chaqiruvi yoki ifoda bo'lishi mumkin.<br />\n<strong>EN:</strong> <code>DEFAULT</code> assigns a value automatically when none is provided. Can be a static value, function call, or expression.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLE tasks (\n    id         SERIAL PRIMARY KEY,\n    status     TEXT DEFAULT 'pending',\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    priority   INT DEFAULT 3,\n    uuid       UUID DEFAULT gen_random_uuid()\n);\n</code></pre>\n<hr />\n<h2 id=\"2-orta-daraja-intermediate\">2. O'rta daraja / Intermediate</h2>\n<p><strong>26. JSONB va JSON farqi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>JSON</code> — matnni aynan saqlaydi (kalit tartibi va bo'sh joylar saqlanadi), har safar so'ralganda parse qilinadi. <code>JSONB</code> — ikkilik (binary) formatda saqlaydi, parse qilingan holda, indekslash mumkin, so'rovlar tezroq. Odatda <code>JSONB</code> afzal.<br />\n<strong>EN:</strong> <code>JSON</code> stores text as-is (preserves key order, whitespace), parsed on every query. <code>JSONB</code> stores in binary format, already parsed, supports indexing, faster queries. Prefer <code>JSONB</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- JSONB so'rovlari / JSONB queries\nSELECT metadata-&gt;&gt;'name' AS name,           -- matn sifatida / as text\n       metadata-&gt;'address'-&gt;&gt;'city' AS city, -- ichki qiymat / nested value\n       metadata @&gt; '{&quot;role&quot;: &quot;admin&quot;}'::jsonb  -- mavjudligi / contains\nFROM users;\n\n-- JSONB indeksi / JSONB index\nCREATE INDEX idx_metadata ON users USING GIN(metadata);\n</code></pre>\n<hr />\n<p><strong>27. ARRAY turlari va so'rovlari?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL massivlarni nativ qo'llab-quvvatlaydi. <code>TEXT[]</code>, <code>INT[]</code> kabi turlar. Massiv elementlariga <code>[n]</code> bilan kiriladi (1 dan boshlanadi), <code>ANY</code>, <code>ALL</code>, <code>@&gt;</code>, <code>&amp;&amp;</code> operatorlari bilan so'raladi.<br />\n<strong>EN:</strong> PostgreSQL natively supports arrays. Access elements with <code>[n]</code> (1-indexed). Use <code>ANY</code>, <code>ALL</code>, <code>@&gt;</code>, <code>&amp;&amp;</code> operators for querying.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLE posts (\n    id    SERIAL PRIMARY KEY,\n    tags  TEXT[]\n);\n\nINSERT INTO posts (tags) VALUES (ARRAY['python', 'fastapi', 'postgresql']);\n\n-- Massiv so'rovlari / Array queries\nSELECT * FROM posts WHERE 'python' = ANY(tags);\nSELECT * FROM posts WHERE tags @&gt; ARRAY['python', 'fastapi'];\nSELECT * FROM posts WHERE tags &amp;&amp; ARRAY['python', 'go'];  -- kesishma / overlap\n</code></pre>\n<hr />\n<p><strong>28. Full-Text Search (To'liq matn qidirish)?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL <code>tsvector</code> va <code>tsquery</code> orqali to'liq matn qidirishni qo'llab-quvvatlaydi. <code>to_tsvector()</code> matnni tokenizatsiya qiladi, <code>to_tsquery()</code> so'rovni yaratadi, <code>@@</code> operatori mos kelishni tekshiradi.<br />\n<strong>EN:</strong> PostgreSQL supports full-text search via <code>tsvector</code> and <code>tsquery</code>. <code>to_tsvector()</code> tokenizes text, <code>to_tsquery()</code> creates search queries, <code>@@</code> checks for matches.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Ustun qo'shish va indeks / Add column and index\nALTER TABLE articles ADD COLUMN search_vector tsvector;\nUPDATE articles SET search_vector = to_tsvector('english', title || ' ' || body);\nCREATE INDEX idx_fts ON articles USING GIN(search_vector);\n\n-- Qidirish / Search\nSELECT title, ts_rank(search_vector, query) AS rank\nFROM articles, to_tsquery('english', 'postgresql &amp; performance') query\nWHERE search_vector @@ query\nORDER BY rank DESC;\n</code></pre>\n<hr />\n<p><strong>29. pg_trgm kengaytmasi nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pg_trgm</code> — trigram asosida matn o'xshashligini hisoblash kengaytmasi. <code>LIKE '%...%'</code> so'rovlarini tezlashtirish uchun GIN/GiST indeksi yaratishga imkon beradi.<br />\n<strong>EN:</strong> <code>pg_trgm</code> is an extension for trigram-based text similarity. Enables GIN/GiST indexes for <code>LIKE '%...%'</code> queries.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE EXTENSION IF NOT EXISTS pg_trgm;\n\nCREATE INDEX idx_trgm ON users USING GIN(name gin_trgm_ops);\n\n-- Tez ILIKE so'rovi / Fast ILIKE query\nSELECT * FROM users WHERE name ILIKE '%ali%';\n\n-- O'xshashlik / Similarity\nSELECT name, similarity(name, 'Alisher') AS sim\nFROM users ORDER BY sim DESC LIMIT 5;\n</code></pre>\n<hr />\n<p><strong>30. Partial Index (Qisman indeks) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Partial Index — faqat ma'lum shartni qanoatlantiruvchi qatorlarga yaratilgan indeks. Kichikroq hajm, tezroq so'rovlar, kam xotira sarfi.<br />\n<strong>EN:</strong> Partial Index is built only on rows satisfying a condition — smaller size, faster queries, less memory.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Faqat faol foydalanuvchilar uchun / Only for active users\nCREATE INDEX idx_active_users ON users(email) WHERE is_active = TRUE;\n\n-- Faqat to'lanmagan buyurtmalar / Only unpaid orders\nCREATE INDEX idx_unpaid ON orders(user_id, created_at)\nWHERE status = 'pending';\n</code></pre>\n<hr />\n<p><strong>31. Composite Index (Ko'p ustunli indeks) qachon samarali?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Ko'p ustunli indeks WHERE da bir nechta ustun filtrlanganda yoki ORDER BY da samarali. Ustunlar tartibi muhim: eng ko'p filtrlangan ustun birinchi bo'lishi kerak. \"Leftmost prefix rule\" — chapdan o'ngga ishlatilishi kerak.<br />\n<strong>EN:</strong> Effective when filtering on multiple columns in WHERE or ORDER BY. Column order matters — most selective column first. \"Leftmost prefix rule\" — used left-to-right.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE INDEX idx_orders_compound ON orders(user_id, status, created_at DESC);\n\n-- Bu indeksdan foydalanadi / Uses index:\nSELECT * FROM orders WHERE user_id = 5 AND status = 'pending';\n\n-- Bu ham foydalanadi / Also uses:\nSELECT * FROM orders WHERE user_id = 5;\n\n-- Bu foydalanmaydi / Does NOT use (status birinchi emas / status not first):\nSELECT * FROM orders WHERE status = 'pending';\n</code></pre>\n<hr />\n<p><strong>32. Covering Index nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Covering Index — so'rov uchun zarur barcha ustunlarni o'z ichiga olgan indeks. PostgreSQL asosiy jadval sahifalariga murojaat qilmasdan (<code>heap fetch</code> yo'q) to'g'ridan-to'g'ri indeksdan javob qaytaradi.<br />\n<strong>EN:</strong> A Covering Index includes all columns needed by a query, allowing PostgreSQL to answer directly from the index without fetching table rows (index-only scan).</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- name va email ham indeksda / name and email also in index\nCREATE INDEX idx_covering ON users(id) INCLUDE (name, email);\n</code></pre>\n<hr />\n<p><strong>33. Table Partitioning nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Partitioning — katta jadvalni kichik fizik qismlarga (partition) bo'lish. So'rovlar faqat tegishli partition da qidiriladi (partition pruning). PostgreSQL da <code>RANGE</code>, <code>LIST</code>, <code>HASH</code> partitioning turlari bor.<br />\n<strong>EN:</strong> Partitioning splits a large table into smaller physical pieces. Queries only search relevant partitions (partition pruning). Types: <code>RANGE</code>, <code>LIST</code>, <code>HASH</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLE orders (\n    id         BIGINT,\n    created_at TIMESTAMPTZ,\n    total      NUMERIC\n) PARTITION BY RANGE (created_at);\n\nCREATE TABLE orders_2024 PARTITION OF orders\n    FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');\n\nCREATE TABLE orders_2025 PARTITION OF orders\n    FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');\n</code></pre>\n<hr />\n<p><strong>34. VACUUM va AUTOVACUUM nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL MVCC tufayli o'chirilgan/yangilangan qatorlarni fizik o'chirmasdan \"o'lik\" (dead tuple) sifatida belgilaydi. <code>VACUUM</code> ushbu o'lik tuplellarni tozalaydi. <code>AUTOVACUUM</code> — fon jarayoni bo'lib, buni avtomatik bajaradi.<br />\n<strong>EN:</strong> PostgreSQL MVCC marks deleted/updated rows as \"dead tuples\" without physically removing them. <code>VACUUM</code> reclaims space from dead tuples. <code>AUTOVACUUM</code> does this automatically in the background.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Qo'lda vacuum / Manual vacuum\nVACUUM ANALYZE users;\n\n-- To'liq tozalash (lock talab qiladi) / Full vacuum (requires lock)\nVACUUM FULL orders;\n\n-- Jadval statistikasini yangilash / Update table statistics\nANALYZE employees;\n</code></pre>\n<hr />\n<p><strong>35. MVCC (Multi-Version Concurrency Control) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> MVCC — PostgreSQL da bir vaqtda o'qish va yozishni lock qilmasdan ta'minlovchi mexanizm. Har bir tranzaksiya ma'lumotlarning o'z \"snapshotini\" ko'radi. Bu o'quvchilar yozuvchilarni bloklamasligini ta'minlaydi.<br />\n<strong>EN:</strong> MVCC allows concurrent reads and writes without locking. Each transaction sees its own \"snapshot\" of data, ensuring readers don't block writers and vice versa.</p>\n</blockquote>\n<hr />\n<p><strong>36. Isolation Level (Izolyatsiya darajasi) turlari?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL 4 ta izolyatsiya darajasini qo'llab-quvvatlaydi:\n- <strong>Read Uncommitted</strong> — PostgreSQL da Read Committed kabi ishlaydi\n- <strong>Read Committed</strong> (default) — faqat tasdiqlangan ma'lumotlarni ko'radi\n- <strong>Repeatable Read</strong> — tranzaksiya davomida bir xil o'qishni kafolatlaydi\n- <strong>Serializable</strong> — to'liq izolyatsiya, xuddi ketma-ket bajariladigan kabi<br />\n<strong>EN:</strong> PostgreSQL supports 4 isolation levels: <strong>Read Uncommitted</strong> (acts as Read Committed), <strong>Read Committed</strong> (default, sees only committed data), <strong>Repeatable Read</strong>, <strong>Serializable</strong> (full isolation).</p>\n</blockquote>\n<pre><code class=\"language-sql\">BEGIN;\nSET TRANSACTION ISOLATION LEVEL REPEATABLE READ;\n-- so'rovlar / queries\nCOMMIT;\n</code></pre>\n<hr />\n<p><strong>37. Lock (Qulf) turlari PostgreSQL da?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Asosiy lock turlari: <strong>ROW-level</strong> (SELECT FOR UPDATE, SELECT FOR SHARE), <strong>TABLE-level</strong> (ALTER TABLE, DROP TABLE), <strong>Advisory Locks</strong> (dastur tomonidan boshqariladigan). <code>pg_locks</code> jadvalidan joriy locklar ko'riladi.<br />\n<strong>EN:</strong> Key lock types: <strong>ROW-level</strong> (SELECT FOR UPDATE/SHARE), <strong>TABLE-level</strong> (ALTER/DROP), <strong>Advisory Locks</strong> (application-controlled). View current locks in <code>pg_locks</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Qator uchun lock / Row-level lock\nSELECT * FROM orders WHERE id = 5 FOR UPDATE;\n\n-- Boshqalar o'qiy oladi, lekin o'zgartira olmaydi / Others can read but not modify\nSELECT * FROM orders WHERE id = 5 FOR SHARE;\n\n-- Advisory lock\nSELECT pg_advisory_lock(12345);\n-- ishlar / work\nSELECT pg_advisory_unlock(12345);\n</code></pre>\n<hr />\n<p><strong>38. Deadlock nima va qanday oldini olish?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Deadlock — ikki tranzaksiya bir-birining resurslarini kutib qolishi. PostgreSQL deadlockni avtomatik aniqlaydi va birini bekor qiladi. Oldini olish: bir xil tartibda locklar olish, tranzaksiyalarni qisqa saqlash.<br />\n<strong>EN:</strong> Deadlock occurs when two transactions wait for each other's resources. PostgreSQL auto-detects and resolves by aborting one. Prevention: acquire locks in consistent order, keep transactions short.</p>\n</blockquote>\n<hr />\n<p><strong>39. TRIGGER nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Trigger — jadvalda ma'lum hodisa (<code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>) sodir bo'lganda avtomatik chaqiriladigan funksiya. <code>BEFORE</code> yoki <code>AFTER</code> hodisaga bog'liq ishga tushadi.<br />\n<strong>EN:</strong> A trigger is a function automatically called when a specific event (<code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>) occurs on a table. Fires <code>BEFORE</code> or <code>AFTER</code> the event.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE OR REPLACE FUNCTION update_timestamp()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE TRIGGER set_timestamp\n    BEFORE UPDATE ON users\n    FOR EACH ROW\n    EXECUTE FUNCTION update_timestamp();\n</code></pre>\n<hr />\n<p><strong>40. Stored Procedure va Function farqi PostgreSQL da?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <strong>Function</strong> — qiymat qaytaradi, SELECT da ishlatilishi mumkin, tranzaksiyani boshqara olmaydi. <strong>Procedure</strong> (PostgreSQL 11+) — qiymat qaytarmaydi, <code>CALL</code> bilan chaqiriladi, <code>COMMIT</code>/<code>ROLLBACK</code> ni o'zi boshqara oladi.<br />\n<strong>EN:</strong> <strong>Function</strong> — returns a value, usable in SELECT, cannot control transactions. <strong>Procedure</strong> (PG 11+) — no return value, called with <code>CALL</code>, can manage its own <code>COMMIT</code>/<code>ROLLBACK</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Function\nCREATE OR REPLACE FUNCTION get_user_orders(p_user_id INT)\nRETURNS TABLE(order_id INT, total NUMERIC) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT id, total FROM orders WHERE user_id = p_user_id;\nEND;\n$$ LANGUAGE plpgsql;\n\nSELECT * FROM get_user_orders(5);\n\n-- Procedure\nCREATE PROCEDURE process_payment(p_order_id INT)\nLANGUAGE plpgsql AS $$\nBEGIN\n    UPDATE orders SET status = 'paid' WHERE id = p_order_id;\n    COMMIT;\nEND;\n$$;\n\nCALL process_payment(42);\n</code></pre>\n<hr />\n<p><strong>41. plpgsql nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> plpgsql — PostgreSQL ning protsessual dasturlash tili. IF/ELSE, LOOP, EXCEPTION bloklari, o'zgaruvchilar, kursorlar va boshqa dasturlash konstruksiyalarini qo'llab-quvvatlaydi. Trigger va funksiyalar yozish uchun ishlatiladi.<br />\n<strong>EN:</strong> plpgsql is PostgreSQL's procedural programming language. Supports IF/ELSE, LOOP, EXCEPTION blocks, variables, cursors. Used to write triggers and functions.</p>\n</blockquote>\n<hr />\n<p><strong>42. UPSERT (<code>INSERT ... ON CONFLICT</code>) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> UPSERT — yozuv mavjud bo'lsa yangilash, yo'q bo'lsa qo'shish. PostgreSQL da <code>INSERT ... ON CONFLICT DO UPDATE</code> yoki <code>ON CONFLICT DO NOTHING</code> bilan amalga oshiriladi.<br />\n<strong>EN:</strong> UPSERT inserts if the row doesn't exist, updates if it does. PostgreSQL uses <code>INSERT ... ON CONFLICT DO UPDATE</code> or <code>ON CONFLICT DO NOTHING</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">INSERT INTO users (email, name, updated_at)\nVALUES ('ali@example.com', 'Ali Karimov', NOW())\nON CONFLICT (email)\nDO UPDATE SET\n    name = EXCLUDED.name,\n    updated_at = EXCLUDED.updated_at;\n</code></pre>\n<hr />\n<p><strong>43. RETURNING clause nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>RETURNING</code> — <code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code> operatsiyasidan keyin o'zgartirilgan qatorlarni qaytaradi. Qo'shimcha SELECT so'rovisiz yangi ID yoki qiymatlarni olish imkonini beradi.<br />\n<strong>EN:</strong> <code>RETURNING</code> returns modified rows after <code>INSERT</code>, <code>UPDATE</code>, or <code>DELETE</code> — gets new IDs or values without an extra SELECT.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Yangi ID ni olish / Get new ID\nINSERT INTO users (name, email) VALUES ('Bobur', 'bobur@test.com')\nRETURNING id, created_at;\n\n-- O'chirilgan yozuvni olish / Get deleted row\nDELETE FROM sessions WHERE expires_at &lt; NOW()\nRETURNING session_token, user_id;\n</code></pre>\n<hr />\n<p><strong>44. Recursive CTE nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Rekursiv CTE — o'z-o'ziga murojaat qiladigan CTE. Ierarxik ma'lumotlar (daraxt tuzilmalari, kategoriya ierarxiyalari, graflar) bilan ishlash uchun ishlatiladi.<br />\n<strong>EN:</strong> Recursive CTE references itself, used for hierarchical data (tree structures, category hierarchies, graphs).</p>\n</blockquote>\n<pre><code class=\"language-sql\">WITH RECURSIVE category_tree AS (\n    -- Boshlang'ich qator / Base case\n    SELECT id, name, parent_id, 0 AS depth\n    FROM categories WHERE parent_id IS NULL\n\n    UNION ALL\n\n    -- Rekursiv qism / Recursive part\n    SELECT c.id, c.name, c.parent_id, ct.depth + 1\n    FROM categories c\n    JOIN category_tree ct ON c.parent_id = ct.id\n)\nSELECT * FROM category_tree ORDER BY depth, name;\n</code></pre>\n<hr />\n<p><strong>45. COPY buyrug'i nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>COPY</code> — PostgreSQL da katta hajmdagi ma'lumotlarni CSV/text fayldan tez import/export qilish buyrug'i. <code>INSERT</code> dan 10-100x tezroq ishlaydi.<br />\n<strong>EN:</strong> <code>COPY</code> is PostgreSQL's fast bulk data import/export from/to CSV/text files — 10-100x faster than <code>INSERT</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Fayldan import / Import from file\nCOPY users(name, email, created_at)\nFROM '/tmp/users.csv'\nWITH (FORMAT csv, HEADER true, DELIMITER ',');\n\n-- Faylga export / Export to file\nCOPY (SELECT * FROM users WHERE is_active = TRUE)\nTO '/tmp/active_users.csv'\nWITH (FORMAT csv, HEADER true);\n</code></pre>\n<hr />\n<p><strong>46. pg_stat_statements nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pg_stat_statements</code> — PostgreSQL kengaytmasi bo'lib, barcha so'rovlar statistikasini (bajarilish sonи, umumiy vaqt, o'rtacha vaqt) kuzatadi. Sekin so'rovlarni topish uchun muhim vosita.<br />\n<strong>EN:</strong> <code>pg_stat_statements</code> is an extension tracking statistics for all queries (execution count, total time, average time). Essential for finding slow queries.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE EXTENSION IF NOT EXISTS pg_stat_statements;\n\n-- Eng sekin so'rovlar / Slowest queries\nSELECT query, calls, total_exec_time/calls AS avg_ms,\n       rows/calls AS avg_rows\nFROM pg_stat_statements\nORDER BY avg_ms DESC\nLIMIT 10;\n</code></pre>\n<hr />\n<p><strong>47. Connection Pooling nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Connection Pooling — ma'lumotlar bazasi ulanishlarini qayta ishlatish mexanizmi. Har safar yangi ulanish yaratish qimmat. <code>PgBouncer</code> yoki <code>pgpool-II</code> eng ko'p ishlatiladigan PostgreSQL connection pooler lar. FastAPI da <code>asyncpg</code> + <code>SQLAlchemy</code> async engine ham pooling qiladi.<br />\n<strong>EN:</strong> Connection Pooling reuses database connections instead of creating new ones each time (expensive). PgBouncer and pgpool-II are popular PostgreSQL poolers.</p>\n</blockquote>\n<hr />\n<p><strong>48. WAL (Write-Ahead Log) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> WAL — PostgreSQL ning o'zgarishlarni jadval sahifalaridan oldin jurnal faylga yozadigan mexanizmi. Crash recovery, streaming replication va Point-in-Time Recovery (PITR) uchun asos.<br />\n<strong>EN:</strong> WAL (Write-Ahead Log) writes changes to a log file before applying them to table pages. Foundation for crash recovery, streaming replication, and PITR.</p>\n</blockquote>\n<hr />\n<p><strong>49. Replication (Replikatsiya) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL replikatsiya turlari:\n- <strong>Streaming Replication</strong> — WAL orqali real-time sinxronizatsiya (primary → standby)\n- <strong>Logical Replication</strong> — jadval darajasida selektiv replikatsiya\n- <strong>Synchronous</strong> — primary standby tasdiqlaguncha kutadi\n- <strong>Asynchronous</strong> — primary kutmaydi (tezroq, lekin ma'lumot yo'qotish xavfi)<br />\n<strong>EN:</strong> Replication types: <strong>Streaming</strong> (real-time via WAL, primary→standby), <strong>Logical</strong> (selective table-level), <strong>Synchronous</strong> (primary waits for standby ACK), <strong>Asynchronous</strong> (primary doesn't wait, faster but risk of data loss).</p>\n</blockquote>\n<hr />\n<p><strong>50. Point-in-Time Recovery (PITR) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PITR — WAL arxivlari yordamida ma'lumotlar bazasini ixtiyoriy o'tgan vaqt nuqtasiga tiklash imkoniyati. \"Ertaga soat 14:30 gacha tiklash kerak\" kabi stsenariylar uchun.<br />\n<strong>EN:</strong> PITR allows restoring the database to any past point in time using WAL archives — for scenarios like \"restore to yesterday 14:30.\"</p>\n</blockquote>\n<hr />\n<p><strong>51. Table Inheritance (Jadval meros olishi) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL jadvallarga meros olishni qo'llab-quvvatlaydi. Parent jadvalga so'rov yuborilganda, barcha child jadval ma'lumotlari ham qaytariladi. Partitioning dan oldin ishlatilgan, hozir asosan deklarativ partitioning afzal.<br />\n<strong>EN:</strong> PostgreSQL supports table inheritance. Querying the parent returns data from all child tables. Largely replaced by declarative partitioning in modern PostgreSQL.</p>\n</blockquote>\n<hr />\n<p><strong>52. UUID va SERIAL/BIGSERIAL o'rtasidagi tanlash?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>SERIAL</code>/<code>BIGSERIAL</code> — ketma-ket, kichik (4/8 bayt), JOIN da tezroq. <code>UUID</code> — global yagona (16 bayt), tarqatilgan tizimlar uchun ideal, lekin indeks hajmi kattaroq, tasodifiy tartib tufayli indeks fragmentatsiyasi ko'p.<br />\n<strong>EN:</strong> <code>SERIAL</code>/<code>BIGSERIAL</code> — sequential, small (4/8 bytes), faster in JOINs. <code>UUID</code> — globally unique (16 bytes), ideal for distributed systems, but larger index size and more fragmentation due to random ordering.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- UUID v4 (tasodifiy / random)\nCREATE TABLE events (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    ...\n);\n\n-- UUID v7 (vaqt tartiblangan / time-ordered) — PostgreSQL 17+\n-- yoki pgcrypto kengaytmasi bilan\n</code></pre>\n<hr />\n<p><strong>53. Generated Columns nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Generated Columns — boshqa ustunlar ifodasi asosida avtomatik hisoblanadigan ustun. <code>STORED</code> — diskda saqlanadi, <code>VIRTUAL</code> — PostgreSQL hali qo'llab-quvvatlamaydi.<br />\n<strong>EN:</strong> Generated Columns are automatically computed from other column expressions. <code>STORED</code> saves to disk; <code>VIRTUAL</code> (not yet in PostgreSQL) computes on read.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLE products (\n    price      NUMERIC,\n    tax_rate   NUMERIC DEFAULT 0.12,\n    price_with_tax NUMERIC GENERATED ALWAYS AS (price * (1 + tax_rate)) STORED\n);\n</code></pre>\n<hr />\n<p><strong>54. Table Statistics va pg_statistic?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL query planneri jadval statistikasiga asoslanib eng yaxshi bajarish rejasini tanlaydi. <code>ANALYZE</code> statistikani yangilaydi. <code>pg_stats</code> ko'rinishi statistikani ko'rsatadi. Noto'g'ri statistika sekin so'rovlarga olib keladi.<br />\n<strong>EN:</strong> PostgreSQL's query planner uses table statistics to choose the best execution plan. <code>ANALYZE</code> updates statistics. <code>pg_stats</code> view shows them. Stale statistics lead to slow queries.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Statistikani yangilash / Update statistics\nANALYZE users;\n\n-- Statistikani ko'rish / View statistics\nSELECT attname, n_distinct, correlation\nFROM pg_stats\nWHERE tablename = 'orders';\n</code></pre>\n<hr />\n<p><strong>55. Lateral Join nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>LATERAL</code> — subquery ning tashqi so'rovning har bir qatoriga murojaat qilishiga imkon beradi. Har bir qator uchun boshqa qiymat bilan subquery ni chaqirish kerak bo'lganda ishlatiladi.<br />\n<strong>EN:</strong> <code>LATERAL</code> allows a subquery to reference columns from the outer query's current row — useful for calling a subquery with different values per row.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Har bir foydalanuvchining oxirgi 3 ta buyurtmasi\nSELECT u.name, o.id, o.total\nFROM users u\nCROSS JOIN LATERAL (\n    SELECT id, total FROM orders\n    WHERE user_id = u.id\n    ORDER BY created_at DESC\n    LIMIT 3\n) o;\n</code></pre>\n<hr />\n<h2 id=\"3-ilgor-daraja-advanced\">3. Ilg'or daraja / Advanced</h2>\n<p><strong>56. Query Planner qanday ishlaydi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Query Planner statistika (jadval hajmi, ustun kardinaliyasi, korrelyatsiya), mavjud indekslar va konfiguratsiya parametrlari asosida eng arzon bajarish rejasini tanlaydi. <code>EXPLAIN</code> orqali rejani ko'rish mumkin.<br />\n<strong>EN:</strong> The Query Planner uses statistics (table size, column cardinality, correlation), available indexes, and config parameters to choose the cheapest execution plan, viewable via <code>EXPLAIN</code>.</p>\n</blockquote>\n<hr />\n<p><strong>57. Parallel Query nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PostgreSQL katta so'rovlarni bir nechta CPU yadroda parallel bajarishini qo'llab-quvvatlaydi. <code>max_parallel_workers_per_gather</code>, <code>parallel_setup_cost</code>, <code>parallel_tuple_cost</code> parametrlari bilan boshqariladi.<br />\n<strong>EN:</strong> PostgreSQL supports executing large queries across multiple CPU cores. Controlled by <code>max_parallel_workers_per_gather</code>, <code>parallel_setup_cost</code>, <code>parallel_tuple_cost</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Parallel so'rovni tekshirish / Check parallel query\nEXPLAIN SELECT COUNT(*), AVG(total) FROM orders;\n-- &quot;Gather&quot; node ko'rsatsa, parallel ishlayapti / &quot;Gather&quot; node = parallel\n</code></pre>\n<hr />\n<p><strong>58. pg_cron kengaytmasi nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pg_cron</code> — PostgreSQL ichida cron-uslubida vazifalarni rejalashtirish imkonini beruvchi kengaytma. Tashqi cron yoki task scheduler kerak emas, to'g'ridan-to'g'ri SQL yoki stored procedure ni jadvallab ishga tushirish mumkin.<br />\n<strong>EN:</strong> <code>pg_cron</code> is an extension for scheduling cron-style jobs inside PostgreSQL — no external cron needed, run SQL or stored procedures on a schedule.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE EXTENSION pg_cron;\n\n-- Har kuni tunda / Every night at midnight\nSELECT cron.schedule('nightly-cleanup', '0 0 * * *',\n    'DELETE FROM sessions WHERE expires_at &lt; NOW()');\n</code></pre>\n<hr />\n<p><strong>59. Tablespace nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Tablespace — PostgreSQL ob'ektlari (jadvallar, indekslar) saqlanadigan disk joyi. Katta, tez-tez foydalaniladigan jadvallarni SSD ga, eski ma'lumotlarni HDD ga joylashtirish imkonini beradi.<br />\n<strong>EN:</strong> Tablespace defines the physical storage location for database objects. Allows placing hot tables on SSD and cold data on HDD.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLESPACE fast_ssd LOCATION '/mnt/ssd/pg_data';\nCREATE TABLE hot_table (...) TABLESPACE fast_ssd;\nCREATE INDEX idx_hot ON hot_table(id) TABLESPACE fast_ssd;\n</code></pre>\n<hr />\n<p><strong>60. PostgreSQL konfiguratsiya asosiy parametrlari?</strong></p>\n<table>\n<thead>\n<tr>\n<th>Parametr</th>\n<th>Tavsiya</th>\n<th>Izoh / Note</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>shared_buffers</code></td>\n<td>RAM ning 25%</td>\n<td>Kesh hajmi / Cache size</td>\n</tr>\n<tr>\n<td><code>work_mem</code></td>\n<td>4MB–64MB</td>\n<td>Sort/hash uchun / Per sort/hash</td>\n</tr>\n<tr>\n<td><code>maintenance_work_mem</code></td>\n<td>256MB+</td>\n<td>VACUUM, index uchun</td>\n</tr>\n<tr>\n<td><code>max_connections</code></td>\n<td>100–200</td>\n<td>PgBouncer bilan kamroq</td>\n</tr>\n<tr>\n<td><code>wal_buffers</code></td>\n<td>16MB</td>\n<td>WAL keshi / WAL cache</td>\n</tr>\n<tr>\n<td><code>checkpoint_completion_target</code></td>\n<td>0.9</td>\n<td>Yumshoq checkpoint</td>\n</tr>\n<tr>\n<td><code>effective_cache_size</code></td>\n<td>RAM ning 75%</td>\n<td>Planner uchun hint</td>\n</tr>\n<tr>\n<td><code>random_page_cost</code></td>\n<td>SSD: 1.1, HDD: 4.0</td>\n<td>Index tanlov uchun</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<p><strong>61. Index Bloat va Table Bloat nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Bloat — MVCC tufayli yig'ilib qolgan o'lik tuple lar va bo'sh indeks sahifalari. <code>VACUUM</code> oddiy bloatni tozalaydi, <code>VACUUM FULL</code> jadvalni to'liq qayta yozadi (lock talab qiladi). <code>pgstattuple</code> kengaytmasi bloatni o'lchaydi.<br />\n<strong>EN:</strong> Bloat is accumulated dead tuples and empty index pages due to MVCC. <code>VACUUM</code> cleans regular bloat; <code>VACUUM FULL</code> rewrites tables (requires lock). Measure with <code>pgstattuple</code>.</p>\n</blockquote>\n<hr />\n<p><strong>62. pg_partman kengaytmasi nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pg_partman</code> — PostgreSQL partition larini avtomatik yaratish va boshqarish kengaytmasi. Yangi oy/hafta/kun boshlanishida avtomatik yangi partition yaratadi va eskilarini arxivlaydi.<br />\n<strong>EN:</strong> <code>pg_partman</code> automates partition creation and management — automatically creates new time-based partitions and archives old ones.</p>\n</blockquote>\n<hr />\n<p><strong>63. Logical Decoding va Change Data Capture (CDC)?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Logical Decoding — WAL oqimini inson o'qiy oladigan formatga (JSON, Avro) aylantirishga imkon beradi. CDC uchun ishlatiladi. <code>wal2json</code>, <code>pgoutput</code> kabi plugin lar bilan Kafka, Debezium bilan integratsiya qilinadi.<br />\n<strong>EN:</strong> Logical Decoding transforms the WAL stream into human-readable formats (JSON, Avro) for CDC. Integrates with Kafka, Debezium via plugins like <code>wal2json</code>, <code>pgoutput</code>.</p>\n</blockquote>\n<hr />\n<p><strong>64. PostGIS kengaytmasi nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>PostGIS</code> — PostgreSQL uchun geografik ob'ektlar qo'llab-quvvatlash kengaytmasi. Nuqta, chiziq, ko'pburchak va boshqa geometrik turlar. Masofani hisoblash, kesishma, koordinata bo'yicha qidirish imkonlari bor.<br />\n<strong>EN:</strong> <code>PostGIS</code> adds geographic object support to PostgreSQL — points, lines, polygons. Supports distance calculation, intersection, coordinate-based search.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE EXTENSION postgis;\n\nCREATE TABLE locations (\n    id   SERIAL PRIMARY KEY,\n    name TEXT,\n    geom GEOMETRY(Point, 4326)  -- WGS 84 koordinatasi\n);\n\n-- 5 km ichidagi joylar / Places within 5km\nSELECT name\nFROM locations\nWHERE ST_DWithin(\n    geom::geography,\n    ST_MakePoint(69.2401, 41.2995)::geography,  -- Toshkent\n    5000  -- metr\n);\n</code></pre>\n<hr />\n<p><strong>65. Foreign Data Wrapper (FDW) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> FDW — PostgreSQL dan boshqa ma'lumotlar manbalari (boshqa PostgreSQL, MySQL, Oracle, CSV, REST API) ga SQL orqali murojaat qilish imkonini beruvchi mexanizm.<br />\n<strong>EN:</strong> FDW allows querying external data sources (other PostgreSQL, MySQL, Oracle, CSV, REST API) via SQL from within PostgreSQL.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE EXTENSION postgres_fdw;\n\nCREATE SERVER remote_db FOREIGN DATA WRAPPER postgres_fdw\nOPTIONS (host '192.168.1.100', dbname 'analytics');\n\nCREATE USER MAPPING FOR current_user\nSERVER remote_db OPTIONS (user 'reader', password 'secret');\n\nCREATE FOREIGN TABLE remote_sales (...)\nSERVER remote_db OPTIONS (schema_name 'public', table_name 'sales');\n\nSELECT * FROM remote_sales WHERE date &gt; '2025-01-01';\n</code></pre>\n<hr />\n<p><strong>66. pgvector kengaytmasi nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pgvector</code> — PostgreSQL da vektor o'xshashlik qidiruvini (vector similarity search) qo'shuvchi kengaytma. AI/ML ilovalar, embedding qidirish, RAG (Retrieval-Augmented Generation) uchun ishlatiladi.<br />\n<strong>EN:</strong> <code>pgvector</code> adds vector similarity search to PostgreSQL — used for AI/ML apps, embedding search, and RAG (Retrieval-Augmented Generation).</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE EXTENSION vector;\n\nCREATE TABLE documents (\n    id        SERIAL PRIMARY KEY,\n    content   TEXT,\n    embedding VECTOR(1536)  -- OpenAI embedding o'lchami\n);\n\nCREATE INDEX ON documents USING ivfflat (embedding vector_cosine_ops);\n\n-- Eng o'xshash hujjatlarni topish / Find most similar documents\nSELECT content, embedding &lt;=&gt; '[0.1, 0.2, ...]'::vector AS distance\nFROM documents\nORDER BY distance\nLIMIT 5;\n</code></pre>\n<hr />\n<p><strong>67. Row Level Security (RLS) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> RLS — jadval darajasida foydalanuvchiga ko'ra qatorlarni filtrlash. Har bir foydalanuvchi faqat o'ziga tegishli ma'lumotlarni ko'radi. Multi-tenant ilovalar uchun ideal.<br />\n<strong>EN:</strong> RLS filters table rows based on the current user — each user sees only their own data. Ideal for multi-tenant applications.</p>\n</blockquote>\n<pre><code class=\"language-sql\">ALTER TABLE orders ENABLE ROW LEVEL SECURITY;\n\n-- Foydalanuvchi faqat o'z buyurtmalarini ko'radi\nCREATE POLICY user_orders ON orders\n    USING (user_id = current_setting('app.current_user_id')::INT);\n\n-- Admin hamma narsani ko'radi\nCREATE POLICY admin_all ON orders\n    TO admin_role\n    USING (TRUE);\n</code></pre>\n<hr />\n<p><strong>68. Asynchronous PostgreSQL (asyncpg) Python da?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>asyncpg</code> — Python uchun eng tez async PostgreSQL driver. FastAPI bilan birgalikda ishlatiladi. <code>SQLAlchemy 2.0</code> ham async rejimni <code>asyncpg</code> orqali qo'llab-quvvatlaydi.<br />\n<strong>EN:</strong> <code>asyncpg</code> is the fastest async PostgreSQL driver for Python. Used with FastAPI. SQLAlchemy 2.0 also supports async mode via <code>asyncpg</code>.</p>\n</blockquote>\n<pre><code class=\"language-python\">import asyncpg\n\nasync def main():\n    conn = await asyncpg.connect(\n        host='localhost', database='mydb',\n        user='postgres', password='secret'\n    )\n    rows = await conn.fetch(\n        'SELECT * FROM users WHERE is_active = $1', True\n    )\n    await conn.close()\n\n# SQLAlchemy async\nfrom sqlalchemy.ext.asyncio import create_async_engine, AsyncSession\n\nengine = create_async_engine(\n    &quot;postgresql+asyncpg://user:pass@localhost/db&quot;,\n    pool_size=10, max_overflow=20\n)\n</code></pre>\n<hr />\n<p><strong>69. Explain output ni qanday o'qish?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> EXPLAIN chiqishidagi asosiy atamalar:\n- <strong>Seq Scan</strong> — to'liq jadval skaneri (indeks yo'q yoki undan foydalanilmayapti)\n- <strong>Index Scan</strong> — indeks orqali qidirish\n- <strong>Index Only Scan</strong> — faqat indeksdan javob (covering index)\n- <strong>Bitmap Heap Scan</strong> — bir nechta indeks natijalarini birlashtirish\n- <strong>Hash Join / Nested Loop / Merge Join</strong> — JOIN strategiyalari\n- <strong>cost=X..Y</strong> — X: birinchi qatorga qiymati, Y: barcha qatorlarga qiymati<br />\n<strong>EN:</strong> Key EXPLAIN terms: <strong>Seq Scan</strong> (full scan, no index), <strong>Index Scan</strong> (uses index), <strong>Index Only Scan</strong> (answer from index alone), <strong>Bitmap Heap Scan</strong> (combines multiple index results), <strong>cost=X..Y</strong> (X: startup, Y: total).</p>\n</blockquote>\n<hr />\n<p><strong>70. pg_dump va pg_restore nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pg_dump</code> — ma'lumotlar bazasining zaxira nusxasini yaratadi (SQL yoki custom format). <code>pg_restore</code> — custom format zaxiralarni tiklaydi. <code>pg_dumpall</code> — barcha MB larni zaxiralaydi.<br />\n<strong>EN:</strong> <code>pg_dump</code> creates database backups (SQL or custom format). <code>pg_restore</code> restores custom format backups. <code>pg_dumpall</code> backs up all databases.</p>\n</blockquote>\n<pre><code class=\"language-bash\"># Custom format (siqilgan / compressed)\npg_dump -h localhost -U postgres -Fc mydb &gt; mydb.dump\n\n# Tiklash / Restore\npg_restore -h localhost -U postgres -d mydb_new mydb.dump\n\n# SQL format\npg_dump -h localhost -U postgres mydb &gt; mydb.sql\n\n# Parallel tiklash (8 ta jarayon / 8 processes)\npg_restore -j 8 -d mydb_new mydb.dump\n</code></pre>\n<hr />\n<p><strong>71. Monitoring uchun muhim PostgreSQL ko'rinishlari?</strong></p>\n<pre><code class=\"language-sql\">-- Faol so'rovlar / Active queries\nSELECT pid, now() - pg_stat_activity.query_start AS duration, query\nFROM pg_stat_activity\nWHERE state = 'active'\nORDER BY duration DESC;\n\n-- Jadval statistikasi / Table statistics\nSELECT schemaname, tablename, n_live_tup, n_dead_tup,\n       last_vacuum, last_autovacuum\nFROM pg_stat_user_tables ORDER BY n_dead_tup DESC;\n\n-- Indeks ishlatilishi / Index usage\nSELECT indexrelname, idx_scan, idx_tup_read\nFROM pg_stat_user_indexes\nORDER BY idx_scan ASC;  -- Kam ishlatiladigan indekslar / Unused indexes\n\n-- Kesh samaradorligi / Cache hit ratio\nSELECT sum(heap_blks_hit) / (sum(heap_blks_hit) + sum(heap_blks_read)) AS ratio\nFROM pg_statio_user_tables;\n-- &gt; 0.99 bo'lishi kerak / Should be &gt; 0.99\n</code></pre>\n<hr />\n<p><strong>72. Unlogged Table nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>UNLOGGED TABLE</code> — WAL ga yozmaydigan jadval. Yozish 10x tezroq, lekin server ishlamay qolsa ma'lumotlar yo'qoladi. Vaqtinchalik ma'lumotlar, kesh jadvallar, test uchun mos.<br />\n<strong>EN:</strong> <code>UNLOGGED TABLE</code> skips WAL writes — 10x faster writes but data is lost on server crash. Good for temporary data, caches, and testing.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE UNLOGGED TABLE temp_calculations (\n    id    SERIAL,\n    value NUMERIC,\n    result NUMERIC\n);\n</code></pre>\n<hr />\n<p><strong>73. PostgreSQL da Sharding nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Sharding — ma'lumotlarni bir nechta PostgreSQL server o'rtasida gorizontal taqsimlash. PostgreSQL nativ sharding ni to'liq qo'llab-quvvatlamaydi — buning uchun <code>Citus</code>, <code>pg_shard</code>, yoki tashqi middleware ishlatiladi.<br />\n<strong>EN:</strong> Sharding distributes data horizontally across multiple PostgreSQL servers. PostgreSQL doesn't natively support full sharding — use <code>Citus</code>, <code>pg_shard</code>, or external middleware.</p>\n</blockquote>\n<hr />\n<p><strong>74. Hot Standby va Streaming Replication sozlash?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Primary da <code>wal_level = replica</code>, <code>max_wal_senders &gt;= 1</code>, <code>hot_standby = on</code> sozlanadi. Standby da <code>primary_conninfo</code> belgilanadi. Standby faqat o'qish (read-only) uchun so'rovlarni qabul qiladi.<br />\n<strong>EN:</strong> On primary: <code>wal_level = replica</code>, <code>max_wal_senders &gt;= 1</code>. On standby: configure <code>primary_conninfo</code>. Standby accepts read-only queries.</p>\n</blockquote>\n<hr />\n<p><strong>75. Expression Index (Ifoda indeksi) nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Expression Index — ustun qiymatidan ko'ra funksiya yoki ifoda natijasiga yaratilgan indeks. So'rovda ham xuddi shu ifoda ishlatilganda indeks qo'llaniladi.<br />\n<strong>EN:</strong> Expression Index is built on a function or expression result, not just a column. The query must use the same expression to use the index.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Katta-kichik harfga bog'liq bo'lmagan email qidirish\nCREATE INDEX idx_lower_email ON users(LOWER(email));\n\n-- Bu so'rov indeksdan foydalanadi / This query uses the index:\nSELECT * FROM users WHERE LOWER(email) = 'ali@example.com';\n\n-- Yil bo'yicha indeks / Index by year\nCREATE INDEX idx_order_year ON orders(EXTRACT(YEAR FROM created_at));\n</code></pre>\n<hr />\n<p><strong>76. Alembic bilan PostgreSQL Migration?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>Alembic</code> — SQLAlchemy uchun ma'lumotlar bazasi migratsiya vositasi. FastAPI + PostgreSQL proyektlarida keng ishlatiladi. <code>alembic revision --autogenerate</code> model o'zgarishlarini avtomatik migratsiyaga aylantiradi.<br />\n<strong>EN:</strong> <code>Alembic</code> is a database migration tool for SQLAlchemy, widely used in FastAPI + PostgreSQL projects. <code>alembic revision --autogenerate</code> auto-generates migrations from model changes.</p>\n</blockquote>\n<pre><code class=\"language-bash\">alembic init alembic\nalembic revision --autogenerate -m &quot;add users table&quot;\nalembic upgrade head\nalembic downgrade -1\n</code></pre>\n<hr />\n<p><strong>77. pg_bouncer sozlash?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> PgBouncer connection pooler sozlamalarining asosiy parametrlari:\n- <code>pool_mode</code>: <code>session</code> (har bir session uchun), <code>transaction</code> (tranzaksiya uchun — eng ommabop), <code>statement</code> (bayonot uchun)\n- <code>max_client_conn</code>: maksimal client ulanishlari\n- <code>default_pool_size</code>: har bir DB/user juftligi uchun ulanishlar soni<br />\n<strong>EN:</strong> Key PgBouncer settings: <code>pool_mode</code> (<code>transaction</code> most popular), <code>max_client_conn</code> (max client connections), <code>default_pool_size</code> (connections per DB/user pair).</p>\n</blockquote>\n<hr />\n<p><strong>78. TOAST nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> TOAST (The Oversized-Attribute Storage Technique) — PostgreSQL da katta qiymatlarni (8KB dan katta) saqlash mexanizmi. Katta TEXT, BYTEA, JSONB qiymatlarini alohida TOAST jadvalida siqib saqlaydi.<br />\n<strong>EN:</strong> TOAST (The Oversized-Attribute Storage Technique) handles large values (&gt;8KB) by compressing and storing them in a separate TOAST table — for TEXT, BYTEA, JSONB.</p>\n</blockquote>\n<hr />\n<p><strong>79. Event Trigger nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Event Trigger — DDL hodisalarida (<code>CREATE</code>, <code>ALTER</code>, <code>DROP</code>) ishga tushadigan trigger. Oddiy trigger DML (INSERT/UPDATE/DELETE) uchun, Event Trigger DDL uchun.<br />\n<strong>EN:</strong> Event Trigger fires on DDL events (<code>CREATE</code>, <code>ALTER</code>, <code>DROP</code>), unlike regular triggers which fire on DML (INSERT/UPDATE/DELETE).</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE OR REPLACE FUNCTION log_ddl()\nRETURNS event_trigger AS $$\nBEGIN\n    INSERT INTO ddl_audit_log(event, command, executed_at)\n    VALUES (tg_event, tg_tag, NOW());\nEND;\n$$ LANGUAGE plpgsql;\n\nCREATE EVENT TRIGGER ddl_logger\nON ddl_command_end\nEXECUTE FUNCTION log_ddl();\n</code></pre>\n<hr />\n<p><strong>80. pg_upgrade nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pg_upgrade</code> — PostgreSQL major versiyasini (masalan, 14 → 16) ma'lumotlarni to'liq dump/restore qilmasdan yangilash vositasi. <code>--link</code> rejimi juda tez, lekin eski versiyaga qaytish imkonsiz.<br />\n<strong>EN:</strong> <code>pg_upgrade</code> upgrades PostgreSQL major versions (e.g., 14→16) without full dump/restore. <code>--link</code> mode is very fast but prevents rollback to old version.</p>\n</blockquote>\n<hr />\n<h2 id=\"4-ekspert-daraja-expert\">4. Ekspert daraja / Expert</h2>\n<p><strong>81. Index Scan vs Bitmap Heap Scan vs Sequential Scan qachon qo'llaniladi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Planner tanlovini belgilovchi omillar: <strong>Seq Scan</strong> — kichik jadvallar yoki ko'p qator qaytarilganda (&gt;15-20% jadval); <strong>Index Scan</strong> — kam qator, random access; <strong>Bitmap Heap Scan</strong> — o'rta miqdordagi qatorlar, bir nechta indeks natijalarini birlashtirish.<br />\n<strong>EN:</strong> <strong>Seq Scan</strong> — small tables or returning many rows (&gt;15-20% of table). <strong>Index Scan</strong> — few rows, random access. <strong>Bitmap Heap Scan</strong> — medium rows, combining multiple index results.</p>\n</blockquote>\n<hr />\n<p><strong>82. Planner nega indeksni ishlatmayapti?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Sabablari: statistika eskirgan (ANALYZE kerak), so'rovda funksiya ishlatilgan (<code>WHERE UPPER(name) = 'ALI'</code> — expression index kerak), indeks ustuni implicit cast bilan ishlatilgan, juda ko'p qator qaytarilishi kutilmoqda, <code>random_page_cost</code> noto'g'ri sozlangan.<br />\n<strong>EN:</strong> Reasons: stale statistics (run ANALYZE), function used on column (needs expression index), implicit type cast, too many rows expected, misconfigured <code>random_page_cost</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- random_page_cost ni SSD uchun tuzatish\nSET random_page_cost = 1.1;\n\n-- Yoki postgresql.conf da\n-- random_page_cost = 1.1\n</code></pre>\n<hr />\n<p><strong>83. N+1 muammosi nima va qanday hal qilish?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> N+1 — 1 ta asosiy so'rov + N ta qo'shimcha so'rov (har bir natija uchun). ORM da ko'p uchraydi. Yechim: <code>JOIN</code> bilan bitta so'rovga birlashtirish, <code>SELECT IN</code>, ORM da eager loading (<code>joinedload</code>, <code>selectinload</code>).<br />\n<strong>EN:</strong> N+1: 1 main query + N additional queries (one per result). Common in ORMs. Fix: combine with <code>JOIN</code>, <code>SELECT IN</code>, or ORM eager loading (<code>joinedload</code>, <code>selectinload</code>).</p>\n</blockquote>\n<pre><code class=\"language-python\"># SQLAlchemy da N+1 / N+1 in SQLAlchemy\n# YOMON / BAD:\nusers = session.query(User).all()\nfor user in users:\n    print(user.orders)  # Har bir user uchun yangi so'rov / New query per user\n\n# YAXSHI / GOOD:\nfrom sqlalchemy.orm import selectinload\nusers = session.query(User).options(selectinload(User.orders)).all()\n</code></pre>\n<hr />\n<p><strong>84. Sharding vs Partitioning farqi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <strong>Partitioning</strong> — bitta PostgreSQL serverida jadvalni bo'laklarga ajratish (mantiqiy va fizik). <strong>Sharding</strong> — ma'lumotlarni bir nechta PostgreSQL server (node) o'rtasida taqsimlash. Sharding gorizontal kengayish (horizontal scaling) uchun.<br />\n<strong>EN:</strong> <strong>Partitioning</strong> — splitting a table within one PostgreSQL server. <strong>Sharding</strong> — distributing data across multiple PostgreSQL servers for horizontal scaling.</p>\n</blockquote>\n<hr />\n<p><strong>85. LISTEN/NOTIFY nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>LISTEN</code>/<code>NOTIFY</code> — PostgreSQL ning o'rnatilgan async xabar almashish mexanizmi. Bir sessiya <code>LISTEN channel</code> qiladi, boshqasi <code>NOTIFY channel, 'payload'</code> yuboradi. Real-time ogohlantirish, pub/sub uchun ishlatiladi.<br />\n<strong>EN:</strong> <code>LISTEN</code>/<code>NOTIFY</code> is PostgreSQL's built-in async messaging. One session <code>LISTEN</code>s, another <code>NOTIFY</code>s. Used for real-time notifications and pub/sub.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Bir sessiyada / In one session:\nLISTEN order_updates;\n\n-- Boshqa sessiyada / In another session:\nNOTIFY order_updates, '{&quot;order_id&quot;: 42, &quot;status&quot;: &quot;shipped&quot;}';\n</code></pre>\n<pre><code class=\"language-python\"># asyncpg bilan / with asyncpg\nasync def listen_notifications():\n    conn = await asyncpg.connect(...)\n    await conn.add_listener('order_updates', callback)\n</code></pre>\n<hr />\n<p><strong>86. pg_logical va Debezium CDC integratsiyasi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pg_logical</code> kengaytmasi yoki PostgreSQL 10+ dagi <code>pgoutput</code> plugin bilan Debezium CDC ni sozlash: <code>wal_level = logical</code> qo'yish, replikatsiya sloti yaratish, Debezium PostgreSQL connectorini sozlash, Kafka topic larida o'zgarishlarni olish.<br />\n<strong>EN:</strong> Configure CDC via <code>pg_logical</code> or <code>pgoutput</code> (PG 10+): set <code>wal_level = logical</code>, create replication slot, configure Debezium PostgreSQL connector, receive changes in Kafka topics.</p>\n</blockquote>\n<hr />\n<p><strong>87. Vakuum agressivligi va bloat boshqaruvi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Muammolar: <code>n_dead_tup</code> yuqori bo'lsa → autovacuum etmayapti. Yechim: <code>autovacuum_vacuum_scale_factor</code> ni kamaytirish, katta jadvallar uchun <code>autovacuum_vacuum_threshold</code> ni sozlash, <code>pg_repack</code> kengaytmasi bilan lock qilmasdan bloatni tozalash.<br />\n<strong>EN:</strong> Problem: high <code>n_dead_tup</code> → autovacuum not keeping up. Fix: lower <code>autovacuum_vacuum_scale_factor</code>, tune <code>autovacuum_vacuum_threshold</code> for large tables, use <code>pg_repack</code> to clean bloat without locks.</p>\n</blockquote>\n<hr />\n<p><strong>88. TimescaleDB nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>TimescaleDB</code> — PostgreSQL uchun vaqt qatorlari ma'lumotlari (time-series) kengaytmasi. Hypertable, continuous aggregation, data retention policies va boshqalar. IoT, monitoring, metrik ma'lumotlar uchun ideal.<br />\n<strong>EN:</strong> <code>TimescaleDB</code> is a PostgreSQL extension for time-series data. Features: hypertables, continuous aggregations, data retention policies. Ideal for IoT, monitoring, metrics.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE EXTENSION timescaledb;\n\nCREATE TABLE metrics (\n    time   TIMESTAMPTZ NOT NULL,\n    device TEXT,\n    value  DOUBLE PRECISION\n);\n\nSELECT create_hypertable('metrics', 'time');\n\n-- Continuous aggregate / Uzluksiz agregat\nCREATE MATERIALIZED VIEW hourly_avg\nWITH (timescaledb.continuous) AS\nSELECT time_bucket('1 hour', time) AS hour, device, AVG(value)\nFROM metrics GROUP BY 1, 2;\n</code></pre>\n<hr />\n<p><strong>89. Patroni nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>Patroni</code> — PostgreSQL uchun yuqori mavjudlik (High Availability) framework. Avtomatik failover, leader election (etcd/ZooKeeper/Consul orqali), configuration management. Kubernetes bilan ham yaxshi ishlaydi.<br />\n<strong>EN:</strong> <code>Patroni</code> is a High Availability framework for PostgreSQL. Provides automatic failover, leader election via etcd/ZooKeeper/Consul, and configuration management. Works well with Kubernetes.</p>\n</blockquote>\n<hr />\n<p><strong>90. PostgreSQL Security hardening?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Asosiy xavfsizlik choralari: <code>pg_hba.conf</code> da IP filtrlash, SSL majburiy qilish (<code>ssl = on</code>), <code>superuser</code> uchun alohida hisob, minimal imtiyoz tamoyili, <code>public</code> schemani o'chirish, <code>pg_audit</code> kengaytmasi bilan audit, parollarni <code>scram-sha-256</code> bilan shifrlash.<br />\n<strong>EN:</strong> Key security measures: IP filtering in <code>pg_hba.conf</code>, enforce SSL (<code>ssl = on</code>), separate superuser account, least privilege principle, revoke <code>public</code> schema, audit with <code>pg_audit</code>, use <code>scram-sha-256</code> for passwords.</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- Public schema dan foydalanishni cheklash\nREVOKE CREATE ON SCHEMA public FROM PUBLIC;\nREVOKE ALL ON DATABASE mydb FROM PUBLIC;\n\n-- Minimal imtiyozli foydalanuvchi yaratish\nCREATE USER app_user WITH PASSWORD 'strong_password';\nGRANT CONNECT ON DATABASE mydb TO app_user;\nGRANT USAGE ON SCHEMA public TO app_user;\nGRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_user;\n</code></pre>\n<hr />\n<p><strong>91. Write-Ahead Log (WAL) arxivlash va PITR sozlash?</strong></p>\n<pre><code class=\"language-bash\"># postgresql.conf\nwal_level = replica\narchive_mode = on\narchive_command = 'cp %p /mnt/wal_archive/%f'\nrestore_command = 'cp /mnt/wal_archive/%f %p'\n\n# Ma'lum vaqtga tiklash / Restore to specific time\nrecovery_target_time = '2025-03-15 14:30:00'\nrecovery_target_action = 'promote'\n</code></pre>\n<hr />\n<p><strong>92. Hyper-optimized so'rov yozish qoidalari?</strong></p>\n<pre><code class=\"language-sql\">-- ❌ YOMON / BAD\nSELECT * FROM orders WHERE EXTRACT(YEAR FROM created_at) = 2025;\n\n-- ✅ YAXSHI / GOOD (indeksdan foydalanadi / uses index)\nSELECT * FROM orders\nWHERE created_at &gt;= '2025-01-01' AND created_at &lt; '2026-01-01';\n\n-- ❌ YOMON / BAD (har qator uchun subquery / subquery per row)\nSELECT name, (SELECT COUNT(*) FROM orders WHERE user_id = u.id) AS cnt\nFROM users u;\n\n-- ✅ YAXSHI / GOOD\nSELECT u.name, COUNT(o.id) AS cnt\nFROM users u LEFT JOIN orders o ON u.id = o.user_id\nGROUP BY u.id, u.name;\n\n-- ❌ YOMON / BAD (IN subquery katta bo'lsa sekin / slow for large IN)\nSELECT * FROM products WHERE id IN (SELECT product_id FROM cart WHERE user_id = 5);\n\n-- ✅ YAXSHI / GOOD\nSELECT p.* FROM products p\nJOIN cart c ON p.id = c.product_id WHERE c.user_id = 5;\n</code></pre>\n<hr />\n<p><strong>93. Fizik va Mantiqiy Replikatsiya farqi?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <strong>Fizik (Streaming)</strong> — butun klaster WAL bloklari ko'rinishida replikatsiya qilinadi, standby faqat o'qish uchun. <strong>Mantiqiy (Logical)</strong> — jadval darajasida, ikki yo'nalishli ham mumkin, version upgradelar orasida ham ishlaydi, selektiv jadvallar tanlanadi.<br />\n<strong>EN:</strong> <strong>Physical (Streaming)</strong> — entire cluster replicated as WAL blocks, standby is read-only. <strong>Logical</strong> — table-level, can be bidirectional, works across versions, selective tables.</p>\n</blockquote>\n<hr />\n<p><strong>94. PostgreSQL da Cursor nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Cursor — katta natija to'plamini qismlarga bo'lib olish imkonini beradi. Butun natijani xotiraga yuklamasdan qatorlarni bittadan yoki batch da olish mumkin.<br />\n<strong>EN:</strong> A cursor allows fetching large result sets in chunks without loading everything into memory at once.</p>\n</blockquote>\n<pre><code class=\"language-sql\">BEGIN;\nDECLARE my_cursor CURSOR FOR\n    SELECT id, name FROM large_table ORDER BY id;\n\nFETCH 100 FROM my_cursor;  -- 100 ta qator olish / Fetch 100 rows\nFETCH 100 FROM my_cursor;  -- Keyingi 100 ta / Next 100\n\nCLOSE my_cursor;\nCOMMIT;\n</code></pre>\n<hr />\n<p><strong>95. pg_stat_bgwriter nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>pg_stat_bgwriter</code> — background writer va checkpoint statistikasini ko'rsatadi. <code>buffers_clean</code> / <code>buffers_alloc</code> nisbati kesh samaradorligini ko'rsatadi. <code>checkpoints_req</code> ko'p bo'lsa, <code>checkpoint_completion_target</code> yoki <code>max_wal_size</code> ni oshirish kerak.<br />\n<strong>EN:</strong> <code>pg_stat_bgwriter</code> shows background writer and checkpoint stats. High <code>checkpoints_req</code> means you need to increase <code>checkpoint_completion_target</code> or <code>max_wal_size</code>.</p>\n</blockquote>\n<pre><code class=\"language-sql\">SELECT checkpoints_timed, checkpoints_req,\n       buffers_checkpoint, buffers_clean,\n       buffers_alloc\nFROM pg_stat_bgwriter;\n</code></pre>\n<hr />\n<p><strong>96. Constraint Exclusion nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>constraint_exclusion</code> — Planner jadval yoki partition da CHECK constraint bo'lsa va so'rov shartiga mos kelmasa, o'sha partition ni butunlay o'tkazib yuboradi. Partition pruning uchun muhim.<br />\n<strong>EN:</strong> <code>constraint_exclusion</code> allows the planner to skip partitions whose CHECK constraint cannot match the query conditions — key for partition pruning.</p>\n</blockquote>\n<pre><code class=\"language-sql\">SET constraint_exclusion = on;\n\n-- Planner faqat mos partition larni skanerlaydi\nSELECT * FROM orders WHERE created_at &gt;= '2025-01-01';\n</code></pre>\n<hr />\n<p><strong>97. Fillfactor nima?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> <code>fillfactor</code> — jadval sahifasining qancha foizi yangi ma'lumot bilan to'ldirish kerakligini belgilaydi. Default: 100. <code>UPDATE</code> ko'p bo'lgan jadvallarda 70-80 qo'yish HOT (Heap Only Tuple) yangilanishlarini tezlashtiradi.<br />\n<strong>EN:</strong> <code>fillfactor</code> sets what percentage of a page to fill with new data (default 100). Setting 70-80 for frequently updated tables enables HOT (Heap Only Tuple) updates — faster updates.</p>\n</blockquote>\n<pre><code class=\"language-sql\">CREATE TABLE orders (...) WITH (fillfactor = 80);\nALTER TABLE orders SET (fillfactor = 80);\nVACUUM FULL orders;  -- Yangi fillfactor bilan qayta yaratish\n</code></pre>\n<hr />\n<p><strong>98. Multi-tenant arxitektura PostgreSQL da?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Uchta yondashuv:\n1. <strong>Alohida MB</strong> — har tenant uchun (eng kuchli izolyatsiya, lekin boshqarish qiyin)\n2. <strong>Alohida Schema</strong> — bitta MB, har tenant uchun schema (o'rta izolyatsiya)\n3. <strong>Shared Tables + RLS</strong> — bitta schema, <code>tenant_id</code> ustuni + Row Level Security (eng ommabop)<br />\n<strong>EN:</strong> Three approaches: 1. <strong>Separate DB</strong> per tenant (strongest isolation, hardest to manage). 2. <strong>Separate Schema</strong> per tenant in one DB. 3. <strong>Shared Tables + RLS</strong> with <code>tenant_id</code> column (most popular).</p>\n</blockquote>\n<pre><code class=\"language-sql\">-- RLS bilan multi-tenant / Multi-tenant with RLS\nALTER TABLE orders ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY tenant_isolation ON orders\n    USING (tenant_id = current_setting('app.tenant_id')::INT);\n\n-- Har so'rov oldidan / Before each query:\nSET app.tenant_id = 42;\nSELECT * FROM orders;  -- Faqat tenant 42 ning buyurtmalari\n</code></pre>\n<hr />\n<p><strong>99. PostgreSQL 16/17 yangiliklari?</strong></p>\n<blockquote>\n<p><strong>UZ:</strong> Muhim yangiliklar:\n- <strong>PG 16:</strong> Logical replication from standby, <code>pg_stat_io</code>, parallel <code>FULL</code> va <code>RIGHT</code> join, <code>COPY FROM</code> WHERE, <code>VACUUM SKIP_DATABASE_STATS</code>\n- <strong>PG 17:</strong> <code>MERGE</code> RETURNING, <code>COPY</code> progress reporting, <code>VACUUM</code> improvements, <code>JSON_TABLE</code>, yaxshilangan <code>EXPLAIN</code> format<br />\n<strong>EN:</strong> PG 16: logical replication from standby, <code>pg_stat_io</code>, parallel FULL/RIGHT joins, <code>COPY FROM WHERE</code>. PG 17: <code>MERGE</code> RETURNING, <code>COPY</code> progress, improved <code>VACUUM</code>, <code>JSON_TABLE</code>, better <code>EXPLAIN</code>.</p>\n</blockquote>\n<hr />\n<p><strong>100. PostgreSQL da eng yaxshi amaliyotlar (Best Practices)?</strong></p>\n<pre><code class=\"language-sql\">-- ✅ 1. Har doim timestamptz ishlatish (UTC saqlash)\ncreated_at TIMESTAMPTZ DEFAULT NOW()\n\n-- ✅ 2. Katta jadvallar uchun partial index\nCREATE INDEX idx_pending ON orders(created_at) WHERE status = 'pending';\n\n-- ✅ 3. Tranzaksiya ichida DDL\nBEGIN;\nALTER TABLE users ADD COLUMN phone TEXT;\nUPDATE users SET phone = 'N/A' WHERE phone IS NULL;\nALTER TABLE users ALTER COLUMN phone SET NOT NULL;\nCOMMIT;\n\n-- ✅ 4. EXPLAIN ANALYZE ni muntazam ishlatish\nEXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) SELECT ...;\n\n-- ✅ 5. Connection timeout va statement timeout\nSET statement_timeout = '30s';\nSET lock_timeout = '5s';\n\n-- ✅ 6. Indeks yaratishda CONCURRENTLY ishlatish (lock yo'q)\nCREATE INDEX CONCURRENTLY idx_new ON large_table(column);\n\n-- ✅ 7. Katta jadvallarni partition qilish\n-- ✅ 8. pg_stat_statements bilan sekin so'rovlarni monitoring\n-- ✅ 9. PgBouncer yoki pgpool-II bilan connection pooling\n-- ✅ 10. WAL arxivlash + PITR sozlash\n</code></pre>\n<hr />\n<h2 id=\"tezkor-yol-yoriq-quick-cheatsheet\">📋 Tezkor Yo'l-Yo'riq / Quick Cheatsheet</h2>\n<h3 id=\"tizim-korinishlari-system-views\">Tizim ko'rinishlari / System Views</h3>\n<pre><code class=\"language-sql\">pg_stat_activity      -- Faol sessiyalar / Active sessions\npg_stat_user_tables   -- Jadval statistikasi / Table stats\npg_stat_user_indexes  -- Indeks statistikasi / Index stats\npg_statio_user_tables -- Kesh statistikasi / Cache stats\npg_stat_statements    -- So'rov statistikasi / Query stats\npg_locks              -- Joriy locklar / Current locks\npg_stat_bgwriter      -- Background writer stats\npg_stat_replication   -- Replikatsiya holati / Replication status\n</code></pre>\n<h3 id=\"muhim-konfiguratsiya-fayllari-key-config-files\">Muhim konfiguratsiya fayllari / Key Config Files</h3>\n<pre><code>postgresql.conf   -- Asosiy konfiguratsiya / Main config\npg_hba.conf       -- Autentifikatsiya qoidalari / Auth rules\npg_ident.conf     -- Foydalanuvchi xaritalash / User mapping\nrecovery.conf     -- Tiklash (PG 12 gacha) / Recovery (pre-PG 12)\n</code></pre>\n<h3 id=\"keng-ishlatiladigan-kengaytmalar-popular-extensions\">Keng ishlatiladigan kengaytmalar / Popular Extensions</h3>\n<pre><code class=\"language-sql\">pg_stat_statements  -- So'rov monitoring / Query monitoring\npgcrypto            -- Kriptografiya / Cryptography\nuuid-ossp           -- UUID generatsiya / UUID generation\npg_trgm             -- Trigram qidirish / Trigram search\npostgis             -- Geografik ma'lumot / Geographic data\npgvector            -- Vektor qidirish / Vector search\ntimescaledb         -- Vaqt qatorlari / Time-series\npg_cron             -- Vazifa rejalashtirish / Job scheduling\npg_partman          -- Partition boshqaruvi / Partition management\npg_repack           -- Bloatsiz defrag / Bloat-free defrag\n</code></pre>\n<h3 id=\"foydali-buyruqlar-useful-commands\">Foydali buyruqlar / Useful Commands</h3>\n<pre><code class=\"language-bash\">psql -h host -U user -d dbname   # Ulanish / Connect\n\\l                                 # MB lar ro'yxati / List DBs\n\\dt                                # Jadvallar / Tables\n\\di                                # Indekslar / Indexes\n\\d tablename                       # Jadval tuzilmasi / Table structure\n\\timing                            # So'rov vaqtini ko'rsatish / Show query time\n\\copy                              # COPY psql orqali / COPY via psql\n\\x                                 # Kengaytirilgan ko'rinish / Expanded view\n</code></pre>\n<hr />\n<p><em>Tayyorlagan / Prepared by: Alyorjon | PostgreSQL 16/17 ga asoslanib</em></p>"};
